use std::{fs, path::Path};
fn replace_once(source:&mut String,from:&str,to:&str,label:&str){let count=source.matches(from).count();assert_eq!(count,1,"compact meter patch {label} expected one match, found {count}");*source=source.replacen(from,to,1);}
pub fn run(out:&Path){let path=out.join("feature_overlays_v170_fixed.rs");let mut source=fs::read_to_string(&path).expect("read generated feature overlay").replace("\r\n","\n");
replace_once(&mut source,r#"unsafe fn paint_dps_with_raid(hdc:HDC,rc:RECT,state:&State){paint_dps(hdc,rc,state);if raid_active(state){paint_raid_rows(hdc,rc,state);}}"#,r#"unsafe fn paint_dps_with_raid(hdc:HDC,rc:RECT,state:&State){if state.compact_mode{if raid_active(state){paint_compact_raid_rows(hdc,rc,state);}else{paint_compact_rows(hdc,rc,state);}return;}paint_dps(hdc,rc,state);if raid_active(state){paint_raid_rows(hdc,rc,state);}}"#,"compact paint switch");
replace_once(&mut source,r#"let rc=logical_client_rect(hwnd,state.scale_percent);let top=dps_rows_top();if y<top||y>=rc.bottom{return None;}let scale=dps_layout_scale(state);let row_h=dps_row_h(scale).max(1);"#,r#"let rc=logical_client_rect(hwnd,state.scale_percent);let top=dps_rows_top_for(state);if y<top||y>=rc.bottom{return None;}let scale=dps_layout_scale(state);let row_h=dps_row_h_for(state,scale).max(1);"#,"raid hit compact");
replace_once(&mut source,r#"let gap=dps_adaptive_logical_px(RAID_CENTER_GAP,scale).max(56);let mid=rc.right/2;let index=if x<mid-gap/2{slot}else if x>mid+gap/2{slot+RAID_ROWS_PER_COLUMN}else{return None;};"#,r#"let gap=if state.compact_mode{dps_adaptive_logical_px(18,scale).max(14)}else{dps_adaptive_logical_px(RAID_CENTER_GAP,scale).max(56)};let mid=rc.right/2;let index=if x<mid-gap/2{slot}else if x>mid+gap/2{slot+RAID_ROWS_PER_COLUMN}else{return None;};"#,"raid compact hit divider");
replace_once(&mut source,r#"unsafe fn hover_badge_at(hwnd:HWND,state:&State,x:i32,y:i32)->Option<String>{if raid_active(state){return None;}"#,r#"unsafe fn hover_badge_at(hwnd:HWND,state:&State,x:i32,y:i32)->Option<String>{if raid_active(state)||state.compact_mode{return None;}"#,"compact hides imagine hover");
source.push_str(r#"
#[cfg(test)]
mod v1290_compact_meter_tests{
    use super::*;
    fn state_stub(compact:bool)->State{let root=std::env::temp_dir();let paths=AppPaths{settings:root.join("settings.json"),log:root.join("readyalert.log"),chat_logs:root.join("ChatLogs"),root};State{kind:Kind::Dps,main_hwnd:null_mut(),paths,features:Arc::new(RwLock::new(FeatureSettings::default())),scale_percent:100,compact_mode:compact,dps:DpsSnapshot::default(),dps_updated_unix_ms:0,image_render_all:false,mechanics:MechanicSnapshot::default(),collapsed:false,expanded:RECT{left:0,top:0,right:600,bottom:400},scroll:0,sort_mode:SortMode::Damage,detail_hwnd:null_mut(),detail_uid:0,settings_hwnd:null_mut(),consumable_hwnd:null_mut(),font:null_mut(),capture_status:String::new(),history:Vec::new(),history_index:None,share_notice:None,hover_text:None,hover_x:0,hover_y:0}}
    #[test]fn semantic_active_state_is_not_index_shifted(){let mut s=state_stub(false);assert!(!toolbar_action_active(&s,ToolbarAction::History));assert!(!toolbar_action_active(&s,ToolbarAction::Older));assert!(toolbar_action_active(&s,ToolbarAction::Live));s.compact_mode=true;assert!(toolbar_action_active(&s,ToolbarAction::Compact));assert!(!toolbar_action_active(&s,ToolbarAction::History));}
    #[test]fn normal_toolbar_has_permanent_compact_control(){let s=state_stub(false);let actions=toolbar_items(&s,900);assert!(actions.iter().any(|i|i.action==ToolbarAction::Compact&&i.label=="C"));assert!(actions.iter().any(|i|i.action==ToolbarAction::Live));}
    #[test]fn compact_toolbar_keeps_c_live_and_history_navigation(){let s=state_stub(true);let actions=toolbar_items(&s,360);for action in[ToolbarAction::Compact,ToolbarAction::Older,ToolbarAction::Live,ToolbarAction::Newer]{assert!(actions.iter().any(|i|i.action==action));}}
    #[test]fn compact_rows_are_thinner_and_minimum_height_is_lower(){assert!(dps_compact_row_h(100)<dps_row_h(100));assert_eq!(overlay_min_height_mode(Kind::Dps,100,true),140);assert_eq!(overlay_min_height_mode(Kind::Dps,100,false),200);}
    #[test]fn compact_size_defaults_are_raid_aware(){let(single_w,single_h)=default_compact_size(100,false);let(raid_w,raid_h)=default_compact_size(100,true);assert!(raid_w>single_w);assert!(raid_h>single_h);}
}
"#);
fs::write(path,source).expect("write compact meter generated overlay");}
